package syntax

func init() {
	doc("abs", "The absolute value of an integer or float.", "alx> abs(-3)", "3", "alx> abs(-2.5)", "2.5")
	doc("byte_size", "The number of bytes in a string, which exceeds String.length for non-ASCII text.", "alx> byte_size(\"héllo\")", "6")
	doc("ceil", "Rounds a float up to an integer.", "alx> ceil(2.1)", "3")
	doc("div", "Integer division, truncating toward zero. Fails on division by zero.", "alx> div(7, 2)", "3", "alx> div(-7, 2)", "-3")
	doc("floor", "Rounds a float down to an integer.", "alx> floor(2.9)", "2")
	doc("hd", "The first element of a list; fails on an empty list.", "alx> hd([1, 2, 3])", "1")
	doc("inspect", "Any value as text in source form, for diagnostics.", "alx> inspect([some(1), none])", "\"[some(1), none]\"", "alx> inspect({\"a\", 1.5})", "\"{\\\"a\\\", 1.5}\"")
	doc("map_size", "The number of entries in a map.", "alx> map_size(%{\"a\" => 1, \"b\" => 2})", "2")
	doc("max", "The greater of two integers, floats or strings.", "alx> max(3, 9)", "9")
	doc("min", "The lesser of two integers, floats or strings.", "alx> min(3, 9)", "3")
	doc("rem", "The remainder of integer division, with the sign of the dividend.", "alx> rem(7, 2)", "1", "alx> rem(-7, 2)", "-1")
	doc("round", "Rounds a float to the nearest integer, halves away from zero.", "alx> round(2.5)", "3")
	doc("tap", "Calls the function with the value for its effect and returns the value. Useful in a pipeline.", "alx> tap(5, fn n -> IO.write(Integer.to_string(n)) end)", "5")
	doc("then", "Passes the value to the function and returns its result. Useful in a pipeline.", "alx> 5 |> then(fn n -> n * 2 end)", "10")
	doc("tl", "The list without its first element; fails on an empty list.", "alx> tl([1, 2, 3])", "[2, 3]")
	doc("to_string", "A string, integer, float or boolean as text. Interpolation \"#{value}\" does the same.", "alx> to_string(42)", "\"42\"", "alx> to_string(true)", "\"true\"")
	doc("trunc", "Drops the fractional part of a float.", "alx> trunc(-2.9)", "-2")
	doc("Function.identity", "Returns its argument.", "alx> Enum.map([1, 2], &Function.identity(&1))", "[1, 2]")

	doc("Bitwise.band", "Bitwise and.", "alx> Bitwise.band(12, 10)", "8")
	doc("Bitwise.bnot", "Bitwise complement.", "alx> Bitwise.bnot(0)", "-1")
	doc("Bitwise.bor", "Bitwise or.", "alx> Bitwise.bor(12, 10)", "14")
	doc("Bitwise.bsl", "Shifts left by a number of bits.", "alx> Bitwise.bsl(1, 4)", "16")
	doc("Bitwise.bsr", "Shifts right by a number of bits, keeping the sign.", "alx> Bitwise.bsr(16, 2)", "4")
	doc("Bitwise.bxor", "Bitwise exclusive or.", "alx> Bitwise.bxor(12, 10)", "6")

	doc("String.at", "The character at a zero-based position as an option; negative positions count from the end.", "alx> String.at(\"héllo\", 1)", "some(\"é\")", "alx> String.at(\"abc\", 9)", "none")
	doc("String.capitalize", "Upper-cases the first character and lower-cases the rest.", "alx> String.capitalize(\"hELLO\")", "\"Hello\"")
	doc("String.codepoints", "The Unicode code points as one-character strings.", "alx> String.codepoints(\"héy\")", "[\"h\", \"é\", \"y\"]")
	doc("String.contains", "Reports whether the string contains the text. Same as String.contains?.", "alx> String.contains(\"alchemy\", \"chem\")", "true")
	doc("String.contains?", "Reports whether the string contains the text, or any of a list of texts.", "alx> String.contains?(\"alchemy\", \"chem\")", "true", "alx> String.contains?(\"alchemy\", [\"gold\", \"lead\", \"my\"])", "true", "alx> String.contains?(\"alchemy\", [])", "false")
	doc("String.count", "Counts non-overlapping occurrences of the text.", "alx> String.count(\"banana\", \"an\")", "2")
	doc("String.downcase", "Lower-cases the string.", "alx> String.downcase(\"HeLLo\")", "\"hello\"")
	doc("String.duplicate", "Repeats the string count times.", "alx> String.duplicate(\"ab\", 3)", "\"ababab\"")
	doc("String.ends_with", "Reports whether the string ends with the suffix. Same as String.ends_with?.", "alx> String.ends_with(\"main.alc\", \".alc\")", "true")
	doc("String.ends_with?", "Reports whether the string ends with the suffix, or with any of a list of suffixes.", "alx> String.ends_with?(\"main.alc\", \".alc\")", "true", "alx> String.ends_with?(\"main.alc\", [\".ex\", \".exs\"])", "false")
	doc("String.first", "The first character as an option.", "alx> String.first(\"abc\")", "some(\"a\")", "alx> String.first(\"\")", "none")
	doc("String.graphemes", "The characters of the string as a list.", "alx> String.graphemes(\"abc\")", "[\"a\", \"b\", \"c\"]")
	doc("String.join", "Joins a list of strings with a separator. Enum.join also accepts numbers and any enumerable.", "alx> String.join([\"a\", \"b\"], \"-\")", "\"a-b\"")
	doc("String.last", "The last character as an option.", "alx> String.last(\"abc\")", "some(\"c\")")
	doc("String.length", "The number of characters (code points).", "alx> String.length(\"héllo\")", "5")
	doc("String.match?", "Reports whether the regular expression matches anywhere in the string.", "alx> String.match?(\"order-42\", ~r/\\d+/)", "true")
	doc("String.next_codepoint", "Splits off the first character, or none for an empty string.", "alx> String.next_codepoint(\"abc\")", "some({\"a\", \"bc\"})")
	doc("String.pad_leading", "Pads on the left to a length, with spaces or the given text.", "alx> String.pad_leading(\"7\", 3, \"0\")", "\"007\"", "alx> String.pad_leading(\"ab\", 4)", "\"  ab\"")
	doc("String.pad_trailing", "Pads on the right to a length, with spaces or the given text.", "alx> String.pad_trailing(\"ab\", 4, \".\")", "\"ab..\"")
	doc("String.printable?", "Reports whether every character is printable.", "alx> String.printable?(\"abc\")", "true")
	doc("String.replace", "Replaces every occurrence of a text, or every match of a regular expression.", "alx> String.replace(\"a-b-c\", \"-\", \"+\")", "\"a+b+c\"", "alx> String.replace(\"a1b22c\", ~r/\\d+/, \"#\")", "\"a#b#c\"")
	doc("String.replace_leading", "Replaces every repetition of a text at the start.", "alx> String.replace_leading(\"aaab\", \"a\", \"x\")", "\"xxxb\"")
	doc("String.replace_prefix", "Replaces a prefix once, when present.", "alx> String.replace_prefix(\"unhappy\", \"un\", \"\")", "\"happy\"")
	doc("String.replace_suffix", "Replaces a suffix once, when present.", "alx> String.replace_suffix(\"main.alc\", \".alc\", \".go\")", "\"main.go\"")
	doc("String.replace_trailing", "Replaces every repetition of a text at the end.", "alx> String.replace_trailing(\"abbb\", \"b\", \"x\")", "\"axxx\"")
	doc("String.reverse", "Reverses the characters.", "alx> String.reverse(\"abc\")", "\"cba\"")
	doc("String.slice", "The substring of a length starting at a zero-based position, or at a range of positions, counted in characters; a negative position counts from the end.", "alx> String.slice(\"hello world\", 6..-1)", "\"world\"", "alx> String.slice(\"alchemy\", 2, 4)", "\"chem\"", "alx> String.slice(\"héllo\", 1, 9)", "\"éllo\"")
	doc("String.split", "Splits on whitespace, on a separator, or wherever a regular expression matches. [parts: n] stops after n pieces, the last holding the rest; [trim: true] leaves out empty pieces.", "alx> String.split(\"k=v=w\", \"=\", [parts: 2])", "[\"k\", \"v=w\"]", "alx> String.split(\",a,,b\", \",\", [trim: true])", "[\"a\", \"b\"]", "alx> String.split(\" a  b \")", "[\"a\", \"b\"]", "alx> String.split(\"a,b,,c\", \",\")", "[\"a\", \"b\", \"\", \"c\"]", "alx> String.split(\"a, b;c\", ~r/[,;]\\s*/)", "[\"a\", \"b\", \"c\"]")
	doc("String.split_at", "Splits into two at a position.", "alx> String.split_at(\"alchemy\", 2)", "{\"al\", \"chemy\"}")
	doc("String.starts_with", "Reports whether the string starts with the prefix. Same as String.starts_with?.", "alx> String.starts_with(\"alchemy\", \"al\")", "true")
	doc("String.starts_with?", "Reports whether the string starts with the prefix, or with any of a list of prefixes.", "alx> String.starts_with?(\"alchemy\", \"al\")", "true", "alx> String.starts_with?(\"alchemy\", [\"gold\", \"alc\"])", "true")
	doc("String.to_float", "Parses a float; fails when the text is not one. Float.parse returns a result instead.", "alx> String.to_float(\"2.5\")", "2.5")
	doc("String.to_integer", "Parses an integer, optionally in a base; fails when the text is not one. Integer.parse returns a result instead.", "alx> String.to_integer(\"42\")", "42", "alx> String.to_integer(\"ff\", 16)", "255")
	doc("String.trim", "Removes whitespace, or repetitions of a text, from both ends.", "alx> String.trim(\"  hi \\n\")", "\"hi\"", "alx> String.trim(\"xxhixx\", \"x\")", "\"hi\"")
	doc("String.trim_leading", "Removes whitespace, or repetitions of a text, from the start.", "alx> String.trim_leading(\"  hi \")", "\"hi \"")
	doc("String.trim_trailing", "Removes whitespace, or repetitions of a text, from the end.", "alx> String.trim_trailing(\"  hi \")", "\"  hi\"")
	doc("String.upcase", "Upper-cases the string.", "alx> String.upcase(\"hello\")", "\"HELLO\"")
	doc("String.valid?", "Reports whether the string is valid UTF-8.", "alx> String.valid?(\"héllo\")", "true")

	doc("Regex.compile", "Compiles a pattern from text, returning an error for an invalid one. A ~r/.../ literal is checked at compile time instead.",
		"alx> case Regex.compile(\"a+\") do", "...>   ok(pattern) -> Regex.match?(pattern, \"caat\")", "...>   error(_) -> false", "...> end", "true")
	doc("Regex.compile!", "Compiles a pattern from text; fails on an invalid one.", "alx> Regex.match?(Regex.compile!(\"^a\"), \"abc\")", "true")
	doc("Regex.match?", "Reports whether the pattern matches anywhere in the string.", "alx> Regex.match?(~r/\\d+/, \"order 42\")", "true", "alx> Regex.match?(~r/^hello/i, \"HELLO there\")", "true")
	doc("Regex.named_captures", "The named groups of the first match, as a map.", "alx> Regex.named_captures(~r/(?P<key>\\w+)=(?P<value>\\w+)/, \"a=1\")", "some(%{\"key\" => \"a\", \"value\" => \"1\"})")
	doc("Regex.replace", "Replaces every match; \\\\1 in the replacement inserts a group.", "alx> Regex.replace(~r/\\d/, \"a1b2\", \"#\")", "\"a#b#\"")
	doc("Regex.run", "The first match followed by its groups, or none.", "alx> Regex.run(~r/(\\w+)@(\\w+)/, \"mail joe@example now\")", "some([\"joe@example\", \"joe\", \"example\"])", "alx> Regex.run(~r/x/, \"abc\")", "none")
	doc("Regex.scan", "Every match, each followed by its groups.", "alx> Regex.scan(~r/\\d+/, \"1 and 22\")", "[[\"1\"], [\"22\"]]")
	doc("Regex.source", "The pattern text.", "alx> Regex.source(~r/a+b/)", "\"a+b\"")
	doc("Regex.split", "Splits the string wherever the pattern matches.", "alx> Regex.split(~r/\\s*,\\s*/, \"a , b,c\")", "[\"a\", \"b\", \"c\"]")

	doc("Integer.ceil_div", "Integer division rounding toward positive infinity.", "alx> Integer.ceil_div(7, 2)", "4")
	doc("Integer.digits", "The digits of a non-negative integer, optionally in a base.", "alx> Integer.digits(123)", "[1, 2, 3]", "alx> Integer.digits(5, 2)", "[1, 0, 1]")
	doc("Integer.extended_gcd", "The greatest common divisor g with coefficients x and y such that a*x + b*y == g.", "alx> Integer.extended_gcd(99, 78)", "{3, -11, 14}")
	doc("Integer.floor_div", "Integer division rounding toward negative infinity.", "alx> Integer.floor_div(-7, 2)", "-4")
	doc("Integer.gcd", "The greatest common divisor.", "alx> Integer.gcd(12, 18)", "6")
	doc("Integer.is_even", "Reports whether the integer is even.", "alx> Integer.is_even(4)", "true")
	doc("Integer.is_odd", "Reports whether the integer is odd.", "alx> Integer.is_odd(4)", "false")
	doc("Integer.mod", "The modulo, with the sign of the divisor.", "alx> Integer.mod(-7, 3)", "2")
	doc("Integer.parse", "Parses an integer, optionally in a base, returning ok(value) or error(reason).", "alx> Integer.parse(\"42\")", "ok(42)", "alx> Integer.parse(\"ff\", 16)", "ok(255)",
		"alx> case Integer.parse(\"4x\") do", "...>   ok(_) -> \"number\"", "...>   error(_) -> \"not a number\"", "...> end", "\"not a number\"")
	doc("Integer.pow", "Raises an integer to a non-negative power.", "alx> Integer.pow(2, 10)", "1024")
	doc("Integer.to_string", "The integer as text, optionally in a base.", "alx> Integer.to_string(255)", "\"255\"", "alx> Integer.to_string(255, 16)", "\"FF\"")
	doc("Integer.undigits", "Builds an integer from its digits, optionally in a base.", "alx> Integer.undigits([1, 2, 3])", "123", "alx> Integer.undigits([1, 0, 1], 2)", "5")

	doc("Float.ceil", "Rounds up, optionally keeping a number of decimal places. Rounding works on the exact value of the float, so 3.7, which is stored as slightly more than 3.7, rounds up to 3.8.", "alx> Float.ceil(2.11, 1)", "2.2", "alx> Float.ceil(2.1)", "3.0", "alx> Float.ceil(3.7, 1)", "3.8", "alx> Float.ceil(12.5, 1)", "12.5")
	doc("Float.floor", "Rounds down, optionally keeping a number of decimal places, working on the exact value of the float: 0.3 is stored as slightly less than 0.3.", "alx> Float.floor(2.19, 1)", "2.1", "alx> Float.floor(0.3, 1)", "0.2")
	doc("Float.from_integer", "Converts an integer to a float.", "alx> Float.from_integer(3)", "3.0")
	doc("Float.parse", "Parses a float, returning ok(value) or error(reason).", "alx> Float.parse(\"2.5\")", "ok(2.5)")
	doc("Float.pow", "Raises a float to a power.", "alx> Float.pow(2.0, 3.0)", "8.0")
	doc("Float.round", "Rounds to the nearest value, optionally keeping a number of decimal places; halves round away from zero. It works on the exact value of the float: 1.15 is stored as slightly less than 1.15.", "alx> Float.round(3.14159, 2)", "3.14", "alx> Float.round(2.5)", "3.0", "alx> Float.round(1.15, 1)", "1.1")
	doc("Float.to_string", "The float as the shortest text that reads back as the same value, in exponent form when that is shorter or the value is at least 2**53, as in Elixir. Interpolation and to_string do the same; inspect keeps plain digits up to 1.0e16.",
		"alx> Float.to_string(2.5)", "\"2.5\"", "alx> Float.to_string(1000.0)", "\"1.0e3\"", "alx> Float.to_string(1250.0)", "\"1250.0\"", "alx> inspect(1000.0)", "\"1000.0\"")

	doc("Base.decode16", "Decodes hexadecimal text, or none when it is invalid.", "alx> Base.decode16(\"6869\")", "some(\"hi\")")
	doc("Base.decode16!", "Decodes hexadecimal text; fails when it is invalid.", "alx> Base.decode16!(\"6869\")", "\"hi\"")
	doc("Base.decode32", "Decodes base 32 text, or none when it is invalid.", "alx> Base.decode32(Base.encode32(\"hi\"))", "some(\"hi\")")
	doc("Base.decode32!", "Decodes base 32 text; fails when it is invalid.", "alx> Base.decode32!(Base.encode32(\"hi\"))", "\"hi\"")
	doc("Base.decode64", "Decodes base 64 text, or none when it is invalid.", "alx> Base.decode64(\"aGk=\")", "some(\"hi\")", "alx> Base.decode64(\"!\")", "none")
	doc("Base.decode64!", "Decodes base 64 text; fails when it is invalid.", "alx> Base.decode64!(\"aGk=\")", "\"hi\"")
	doc("Base.encode16", "Encodes bytes as hexadecimal text.", "alx> String.downcase(Base.encode16(\"hi\"))", "\"6869\"")
	doc("Base.encode32", "Encodes bytes as base 32 text.", "alx> Base.encode32(\"hi\")", "\"NBUQ====\"")
	doc("Base.encode64", "Encodes bytes as base 64 text.", "alx> Base.encode64(\"hi\")", "\"aGk=\"")
	doc("Base.url_decode64", "Decodes URL-safe base 64 text, or none when it is invalid.", "alx> Base.url_decode64(Base.url_encode64(\"hi?\"))", "some(\"hi?\")")
	doc("Base.url_decode64!", "Decodes URL-safe base 64 text; fails when it is invalid.", "alx> Base.url_decode64!(Base.url_encode64(\"hi?\"))", "\"hi?\"")
	doc("Base.url_encode64", "Encodes bytes as base 64 text using the URL-safe alphabet.", "alx> Base.url_encode64(\"hi\")", "\"aGk=\"")

	doc("JSON.decode", "Parses JSON text into the JSON type, whose constructors are JSON.null, JSON.boolean, JSON.integer, JSON.float, JSON.string, JSON.list and JSON.object.",
		"alx> JSON.decode(\"[1, true]\")", "ok(JSON.list([JSON.integer(1), JSON.boolean(true)]))",
		"alx> case JSON.decode(\"{\") do", "...>   ok(_) -> \"valid\"", "...>   error(_) -> \"invalid\"", "...> end", "\"invalid\"")
	doc("JSON.decode!", "Parses JSON text; fails when it is invalid.", "alx> JSON.decode!(\"{\\\"a\\\": null}\")", "JSON.object(%{\"a\" => JSON.null})")
	doc("JSON.encode!", "Writes a JSON value as text, with object keys in ascending order.", "alx> JSON.encode!(JSON.object(%{\"name\" => JSON.string(\"al\"), \"tags\" => JSON.list([JSON.integer(1)])}))", "\"{\\\"name\\\":\\\"al\\\",\\\"tags\\\":[1]}\"")
}
